$decision=Read-Doc 'governance/decisions/kf06-visibility-amendment-02.md';foreach($v in @('ANCESTRALIDADE-CTO-DEC-KF06-VISIBILITY-02','PRESIDENCY_CTO_VIA_USER_MESSAGE','PRIVATE_VISIBILITY_REQUIREMENT_ONLY','SUPERSEDED','OPEN_DEVELOPMENT','NOT_ESTABLISHED','PREFERRED_DEV_CANDIDATE','REFERENCED_NOT_RECEIVED','END OF DECISION')){if(-not $decision.Contains($v)){$issues.Add('Decisão incompleta: '+$v)}}
