if($manifest.accepted_documentation_sha -ne 'dad48511595f1d0fa3d06590da222cc0fabaef0a' -or $manifest.references.Count -ne 14 -or $manifest.decisions.Count -ne 16 -or $manifest.functional_requirements.Count -ne 14){$issues.Add('Rastreabilidade normativa original alterada')}
foreach($r in $published.records){$local=Git-Value $root @('rev-parse',($r.ref+':'+$r.path));if($local -ne $r.blob){$issues.Add('Publicação/blobs divergentes: '+$r.path)}}
foreach($r in $manifest.bootstrap_records){$proof=$published.records|Where-Object path -eq $r.canonical_path;if($r.ref -ne $proof.ref -or $r.git_blob -ne $proof.blob -or $r.status -ne 'PUBLISHED_AT_OBSERVED_COMMIT_NOT_FINAL_ACCEPTANCE'){$issues.Add('REQ/IMP/VAL sem referência publicada precisa: '+$r.id)}}
$tables=@(@{p='decisions/DECISION-REGISTER.md';pattern='(?m)^\| DEC-\d{2} \|[^\r\n]+';n=16},@{p='product/M01-FUNCTIONAL-REQUIREMENTS.md';pattern='(?m)^\| R\d{2} \|[^\r\n]+';n=14},@{p='validation/M01-ACCEPTANCE-CRITERIA.md';pattern='(?m)^\| MVP:AC-\d{2} \|[^\r\n]+';n=18})
foreach($r in $tables){$old=Git-Value $root @('show',($baseline.docs_head+':'+$r.p));$now=Read-Doc $r.p;$a=@([regex]::Matches($old,$r.pattern)|ForEach-Object{$_.Value});$b=@([regex]::Matches($now,$r.pattern)|ForEach-Object{$_.Value});if($a.Count -ne $r.n -or ($a -join "`n") -cne ($b -join "`n")){$issues.Add('Alteração substantiva fora da emenda: '+$r.p)}}
$wp=Read-Doc 'research/WP02-VERCEL-HOBBY-DEV-01.md';foreach($v in @('PREFERRED_DEV_CANDIDATE','NON_COMMERCIAL_ELIGIBILITY_NOT_ESTABLISHED','OFFICIAL_DOCUMENTATION_DISCREPANCY','ENVIRONMENT_MAPPING_REQUIRED','CAPACITY_AND_TOTAL_COST_NOT_ESTABLISHED','SECRET_HANDLING_QUALIFICATION_REQUIRED','EXIT_AND_EVOLUTION_PLAN_REQUIRED','https://vercel.com/legal/terms','https://vercel.com/docs/git','https://vercel.com/docs/limits','https://vercel.com/docs/deployments/environments')){if(-not $wp.Contains($v)){$issues.Add('Qualificação WP-02 incompleta: '+$v)}}
$state=(Read-Doc 'status/CURRENT-STATUS.md').Replace('**','');foreach($v in @('PUBLIC','OPEN_DEVELOPMENT','SUPERSEDED','NOT_ESTABLISHED','REFERENCED_NOT_RECEIVED','CTO_APPLICATION_REPOSITORY_FINAL_ACCEPTANCE_REVIEW')){if(-not $state.Contains($v)){$issues.Add('Estado corrente incompleto: '+$v)}}
$docs=@(Get-ChildItem -LiteralPath $root -Recurse -File -Filter '*.md'|Where-Object{$_.FullName -notmatch '[\\/]\.git[\\/]'});$appDocs=@(Get-ChildItem -LiteralPath $AppRoot -Recurse -File -Filter '*.md'|Where-Object{$_.FullName -notmatch '[\\/]\.git[\\/]'})
$ids=@{};$references=0;$metadata=@();$sensitive=@('gh[pousr]_[A-Za-z0-9]{30,}','github_pat_[A-Za-z0-9_]{40,}','AKIA[0-9A-Z]{16}','-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----','\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b','\b\d{3}\.\d{3}\.\d{3}-\d{2}\b','C:[\\/]Users[\\/]')
foreach($f in @($docs)+@($appDocs)){$isApp=$f.FullName.StartsWith($AppRoot,[StringComparison]::OrdinalIgnoreCase);$folder=if($isApp){$AppRoot}else{$root};$rel=$f.FullName.Substring($folder.Length+1).Replace('\','/');$label=$(if($isApp){'app/'}else{'docs/'})+$rel;$t=[IO.File]::ReadAllText($f.FullName);$h=[regex]::Match($t,'(?s)\A---\r?\n(.*?)\r?\n---\r?\n');if(-not $h.Success){$issues.Add('Frontmatter ausente: '+$label);continue};$m=$h.Groups[1].Value;foreach($k in @('id','title','version','status','authority','maintainer','module','classification','references','supersedes','last_updated')){if($m -notmatch ('(?m)^'+$k+':')){$issues.Add('Metadado ausente: '+$label+'/'+$k)}};$id=[regex]::Match($m,'(?m)^id:\s*(\S+)').Groups[1].Value;if($ids.ContainsKey($id)){$issues.Add('ID duplicado: '+$id)}else{$ids[$id]=$label}
 if($m -notmatch '(?m)^classification: PUBLIC\s*$' -or $m -match '"[ \t]+- "' -or $t.Contains([char]0xFFFD) -or ([regex]::Matches($t,'(?m)^```').Count % 2)){$issues.Add('Classificação/formato inválido: '+$label)}
 $targets=@([regex]::Matches($t.Substring($h.Length),'\]\(([^)]+)\)')|ForEach-Object{$_.Groups[1].Value});$targets+=@([regex]::Matches($m,'(?m)^  - "([^"\r\n]+)"\s*$')|ForEach-Object{$_.Groups[1].Value});foreach($target in $targets){if($target -match '^(https?:|mailto:|#)'){continue};$references++;$resolved=[IO.Path]::GetFullPath((Join-Path $f.DirectoryName (($target.Trim('<','>') -split '#',2)[0])));if($resolved -in @((Join-Path $root $output),(Join-Path $root $docsPatch),(Join-Path $root $appPatch))){continue};if(-not (Test-Path -LiteralPath $resolved)){$issues.Add('Link inexistente: '+$label+' -> '+$target)}}
 foreach($pattern in $sensitive){if([regex]::IsMatch($t,$pattern,[Text.RegularExpressions.RegexOptions]::IgnoreCase)){$issues.Add('Padrão sensível, conteúdo omitido: '+$label)}}
 if($isApp -or $rel -in $allowedModified){$base=if($isApp){$baseline.app_head}else{$baseline.docs_head};$old=Git-Value $folder @('show',($base+':'+$rel));$v=[regex]::Match($old,'(?m)^version: "([^"]+)"').Groups[1].Value;$parts=$v.Split('.');$next=$parts[0]+'.'+([int]$parts[1]+1);if($m -notmatch ('(?m)^version: "'+[regex]::Escape($next)+'"') -or -not $m.Contains($base+':'+$rel+'@'+$v)){$issues.Add('Versão/proveniência anterior inválida: '+$label)}}
 if($isApp -or $rel -in $allowedModified -or $rel -in $allowedNew){$metadata+=[ordered]@{repository=$(if($isApp){'app'}else{'docs'});path=$rel;id=$id;version=[regex]::Match($m,'(?m)^version: "([^"]+)"').Groups[1].Value;status=[regex]::Match($m,'(?m)^status:\s*(\S+)').Groups[1].Value}}
}
foreach($p in $appAllowed){$t=[IO.File]::ReadAllText((Join-Path $AppRoot $p));foreach($pattern in $sensitive){if([regex]::IsMatch($t,$pattern,[Text.RegularExpressions.RegexOptions]::IgnoreCase)){$issues.Add('Padrão sensível App atual, conteúdo omitido: '+$p)}}}
$val=Read-Doc 'validation/VAL-KF06-VISIBILITY-02.md';$criteria=@([regex]::Matches($val,'(?m)^\| (AC-VIS-\d{2}) \|[^\r\n]*? \| (PASS|FAIL|BLOCKED|NOT_EXECUTED) \|')|ForEach-Object{[ordered]@{id=$_.Groups[1].Value;result=$_.Groups[2].Value}});if($criteria.Count -ne 8 -or @($criteria|Where-Object result -ne 'PASS').Count){$issues.Add('Matriz documental da emenda inconsistente')}
$changed=@(Lines (Git-Value $root @('-c','core.safecrlf=false','diff','--name-only')));$new=@(Lines (Git-Value $root @('ls-files','--others','--exclude-standard')));foreach($p in @($output,$docsPatch,$appPatch)){if($p -notin $new){$new+=$p}};foreach($p in @($changed)+@($new)){if($p -notin $allowedModified -and $p -notin $allowedNew){$issues.Add('Arquivo docs fora de escopo: '+$p)}}
$appChanged=@(Lines (Git-Value $AppRoot @('-c','core.safecrlf=false','diff','--name-only')));if((Compare-Object ($appChanged|Sort-Object) ($appAllowed|Sort-Object)) -or (Git-Value $AppRoot @('ls-files','--others','--exclude-standard'))){$issues.Add('Escopo de alteração App diverge dos cinco arquivos')}
$check=Git-Read $root @('-c','core.safecrlf=false','diff','--check');$appCheck=Git-Read $AppRoot @('-c','core.safecrlf=false','diff','--check');if($check.exit_code -or $appCheck.exit_code){$issues.Add('git diff --check falhou')}
$result=[ordered]@{id='ANCESTRALIDADE-VAL-KF06-VISIBILITY-02-LOCAL';recorded_on=(Get-Date -Format 'yyyy-MM-dd');executor='AGENT_CODER';decision='ANCESTRALIDADE-CTO-DEC-KF06-VISIBILITY-02';docs_head=$head;app_head=$appHead;docs_modified=$changed;docs_new=$new;docs_preserved=$preservation.Count;preservation=$preservation;app_changed=$appHashes;app_visibility='public';remote_operation=$remote.operation;remote_patch_performed=$remote.patch_performed;remote_public_anonymous_read='PASS';pre_change_security='PASS';security_scope=$security.scope;remote_history_commits=$security.remote_reachable_commits.Count;local_history_commits=$security.local_reachable_commit_count;history_blobs=$security.history_blobs.Count;post_change_patterns='PASS_IF_NO_ERRORS';markdown_docs=$docs.Count;markdown_app=$appDocs.Count;unique_ids=$ids.Count;references_checked=$references;metadata=$metadata;acceptance=$criteria;acceptance_counts=@{PASS=8;FAIL=0;BLOCKED=0;NOT_EXECUTED=0};previous_private_requirement='SUPERSEDED_VISIBILITY_ONLY';open_source_license='NOT_ESTABLISHED';legal_ownership='NOT_ESTABLISHED';production_hosting='NOT_ESTABLISHED';vercel_hobby='PREFERRED_DEV_CANDIDATE_QUALIFICATION_OPEN';integration_parent_authorization='REFERENCED_NOT_RECEIVED';git_integration='NOT_EXECUTED_GATES_PRESERVED';commit_push_merge_performed=$false;M01_implementation='NOT_AUTHORIZED';engineering_readiness='NOT_ESTABLISHED';domain_contracts='NOT_FROZEN';historical_evidence_overwritten=$false;historical_validators_reexecuted=$false;diff_check=$(if($check.exit_code -or $appCheck.exit_code){'FAIL'}else{'PASS'});errors=@($issues);result=$(if($issues.Count){'FAIL'}else{'PASS'});docs_patch=$docsPatch;app_patch=$appPatch;next_gate='CTO_APPLICATION_REPOSITORY_FINAL_ACCEPTANCE_REVIEW';limits=@('Pattern scan and scoped human content/history review are not an exhaustive security guarantee','Offline validation checks recorded authenticated/public API proofs; does not repeat remote authentication','Vercel qualification is documentary, not eligibility determination, provider validation or deploy approval','Full parent integration authorization not received; no Git operation parameters invented','Patch files exclude themselves to avoid circular diffs')}
[IO.File]::WriteAllText((Join-Path $root $output),($result|ConvertTo-Json -Depth 15),$encoding)
$patch=Git-Value $root @('-c','core.safecrlf=false','diff','--no-ext-diff','--no-color');$patch+="`n";foreach($p in $new|Where-Object{$_ -notin @($docsPatch,$appPatch)}|Sort-Object){$r=Git-Read $root @('-c','core.safecrlf=false','diff','--no-index','--no-ext-diff','--no-color','--','/dev/null',$p);if($r.exit_code -notin @(0,1)){throw 'New file diff failed'};$patch+=$r.stdout+"`n"};[IO.File]::WriteAllText((Join-Path $root $docsPatch),$patch,$encoding)
$patchApp=Git-Value $AppRoot @('-c','core.safecrlf=false','diff','--no-ext-diff','--no-color');[IO.File]::WriteAllText((Join-Path $root $appPatch),($patchApp+"`n"),$encoding)
foreach($p in @($changed)+@($new|Where-Object{$_ -notin @($docsPatch,$appPatch)})){if(-not $patch.Contains('+++ b/'+$p)){throw ('Diff docs incompleto: '+$p)}};foreach($p in $appAllowed){if(-not $patchApp.Contains('+++ b/'+$p)){throw ('Diff App incompleto: '+$p)}}
[pscustomobject]@{result=$result.result;docs_modified=$changed.Count;docs_created=$new.Count;docs_preserved=$preservation.Count;app_updated=$appChanged.Count;markdown_docs=$docs.Count;markdown_app=$appDocs.Count;references_checked=$references;criteria=$criteria.Count;errors=@($issues)}|ConvertTo-Json -Depth 5
if($issues.Count){throw 'Validação VISIBILITY-02 falhou; consultar evidência própria'}
